export function deepClone<T>(target: T): T {
    if (target === null || typeof target !== 'object') return target;
    if (Array.isArray(target)) {
        return target.map(item => deepClone(item)) as unknown as T;
    }
    const copy = {} as Record<string, any>;
    for (const key of Object.keys(target as Record<string, any>)) {
        copy[key] = deepClone((target as Record<string, any>)[key]);
    }
    return copy as T;
}

export function deepMerge<T extends Record<string, any>, U extends Record<string, any>>(target: T, source: U): T & U {
    const output = deepClone(target) as any;
    for (const key of Object.keys(source)) {
        if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
            output[key] = deepMerge(output[key] || {}, source[key]);
        } else {
            output[key] = deepClone(source[key]);
        }
    }
    return output as T & U;
}
```

### Complexity:
- Time: O(N) where N is total node count
- Space: O(N)

### Explanation:
1. Handle primitives and null directly by returning value.
2. Branch array cloning using map and recursive deepClone.
3. Merge objects recursively, overriding primitives and combining sub-objects.

