type Handler<T> = (data: T) => void;

export class TypedEventEmitter<Events extends Record<string, any>> {
    private listeners: { [K in keyof Events]?: Set<Handler<Events[K]>> } = {};

    on<K extends keyof Events>(event: K, handler: Handler<Events[K]>): () => void {
        if (!this.listeners[event]) {
            this.listeners[event] = new Set();
        }
        this.listeners[event]!.add(handler);
        return () => this.off(event, handler);
    }

    off<K extends keyof Events>(event: K, handler: Handler<Events[K]>): void {
        this.listeners[event]?.delete(handler);
    }

    once<K extends keyof Events>(event: K, handler: Handler<Events[K]>): void {
        const wrapper: Handler<Events[K]> = (data: Events[K]) => {
            this.off(event, wrapper);
            handler(data);
        };
        this.on(event, wrapper);
    }

    emit<K extends keyof Events>(event: K, data: Events[K]): void {
        const subs = this.listeners[event];
        if (subs) {
            subs.forEach(fn => fn(data));
        }
    }
}
```

### Complexity:
- Time: O(1) subscribe, O(S) emit where S is subscribers count
- Space: O(S)

### Explanation:
1. Constrain event map to generic Record<string, any>.
2. Use Set<Handler> for O(1) deduplication and removal.
3. Return unsubscribe lambda from on() for clean teardown.

