export class PromisePool {
    private active = 0;
    private queue: Array<() => void> = [];

    constructor(public concurrency: number) {}

    async run<T>(task: () => Promise<T>, timeoutMs?: number): Promise<T> {
        if (this.active >= this.concurrency) {
            await new Promise<void>(resolve => this.queue.push(resolve));
        }
        this.active++;
        try {
            if (timeoutMs !== undefined && timeoutMs > 0) {
                return await Promise.race([
                    task(),
                    new Promise<T>((_, reject) => setTimeout(() => reject(new Error('Task timeout')), timeoutMs))
                ]);
            }
            return await task();
        } finally {
            this.active--;
            if (this.queue.length > 0) {
                const next = this.queue.shift();
                if (next) next();
            }
        }
    }
}
```

### Complexity:
- Time: O(1) queue overhead per task
- Space: O(Q) pending queue size

### Explanation:
1. Maintain active counter and FIFO queue of pending resolver functions.
2. If active >= concurrency, await queue push promise.
3. Execute task wrapped in Promise.race with optional timeout timer.
4. In finally block, decrement active count and pop next waiter.

### Unit Tests:
```typescript
import { describe, it, expect } from 'vitest';

describe('PromisePool', () => {
    it('should limit concurrent tasks to configured limit', async () => {
        const pool = new PromisePool(2);
        let running = 0;
        let maxRunning = 0;
        const makeTask = () => async () => {
            running++;
            maxRunning = Math.max(maxRunning, running);
            await new Promise(r => setTimeout(r, 20));
            running--;
            return true;
        };
        await Promise.all([pool.run(makeTask()), pool.run(makeTask()), pool.run(makeTask()), pool.run(makeTask())]);
        expect(maxRunning).toBe(2);
    });
});
```

