class MinHeap<T> {
    private heap: T[] = [];
    constructor(private compare: (a: T, b: T) => number) {}
    push(item: T) {
        this.heap.push(item);
        this._bubbleUp(this.heap.length - 1);
    }
    pop(): T | undefined {
        if (this.heap.length <= 1) return this.heap.pop();
        const top = this.heap[0];
        this.heap[0] = this.heap.pop()!;
        this._bubbleDown(0);
        return top;
    }
    get size(): number { return this.heap.length; }
    private _bubbleUp(i: number) {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.compare(this.heap[i], this.heap[p]) < 0) {
                [this.heap[i], this.heap[p]] = [this.heap[p], this.heap[i]];
                i = p;
            } else break;
        }
    }
    private _bubbleDown(i: number) {
        const len = this.heap.length;
        while ((i << 1) + 1 < len) {
            let left = (i << 1) + 1;
            let right = left + 1;
            let smallest = i;
            if (left < len && this.compare(this.heap[left], this.heap[smallest]) < 0) smallest = left;
            if (right < len && this.compare(this.heap[right], this.heap[smallest]) < 0) smallest = right;
            if (smallest !== i) {
                [this.heap[i], this.heap[smallest]] = [this.heap[smallest], this.heap[i]];
                i = smallest;
            } else break;
        }
    }
}

export function dijkstra(n: number, edges: [number, number, number][], start: number): number[] {
    const adj: [number, number][][] = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
    }
    const dist = new Array(n).fill(Infinity);
    dist[start] = 0;
    const heap = new MinHeap<[number, number]>((a, b) => a[0] - b[0]);
    heap.push([0, start]);
    while (heap.size > 0) {
        const [d, u] = heap.pop()!;
        if (d > dist[u]) continue;
        for (const [v, w] of adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap.push([dist[v], v]);
            }
        }
    }
    return dist;
}
```

### Complexity:
- Time: O((V + E) log V)
- Space: O(V + E)

### Explanation:
1. Implement generic binary min-heap with bubble-up and bubble-down.
2. Construct adjacency list mapping node u to list of (v, weight) edges.
3. Relax edges iteratively; skip nodes already processed with lower distance.

