#include <cstddef>
#include <stdexcept>
#include <utility>

template<typename T>
class Vector {
private:
    T* data_;
    size_t size_;
    size_t cap_;

    void reallocate(size_t new_cap) {
        T* new_data = new T[new_cap];
        for (size_t i = 0; i < size_; ++i) {
            new_data[i] = std::move(data_[i]);
        }
        delete[] data_;
        data_ = new_data;
        cap_ = new_cap;
    }

public:
    Vector() : data_(nullptr), size_(0), cap_(0) {}
    ~Vector() { delete[] data_; }

    void push_back(const T& val) {
        if (size_ == cap_) {
            reallocate(cap_ == 0 ? 1 : cap_ * 2);
        }
        data_[size_++] = val;
    }

    void pop_back() {
        if (size_ > 0) --size_;
    }

    T& operator[](size_t idx) {
        if (idx >= size_) throw std::out_of_range("Index out of range");
        return data_[idx];
    }

    const T& operator[](size_t idx) const {
        if (idx >= size_) throw std::out_of_range("Index out of range");
        return data_[idx];
    }

    size_t size() const { return size_; }
    size_t capacity() const { return cap_; }
};
```

### Complexity:
- Time: O(1) amortized push_back
- Space: O(capacity)

### Explanation:
1. Allocate raw array dynamically with double capacity on overflow.
2. Move elements during reallocation and free old memory.
3. Destructor releases memory to eliminate memory leaks.

