#include <queue>
#include <mutex>
#include <condition_variable>

template<typename T>
class BlockingQueue {
private:
    std::queue<T> queue_;
    size_t max_size_;
    std::mutex mtx_;
    std::condition_variable cv_not_full_;
    std::condition_variable cv_not_empty_;

public:
    explicit BlockingQueue(size_t max_size) : max_size_(max_size) {}

    void push(T item) {
        std::unique_lock<std::mutex> lock(mtx_);
        cv_not_full_.wait(lock, [this]() { return queue_.size() < max_size_; });
        queue_.push(std::move(item));
        cv_not_empty_.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(mtx_);
        cv_not_empty_.wait(lock, [this]() { return !queue_.empty(); });
        T item = std::move(queue_.front());
        queue_.pop();
        cv_not_full_.notify_one();
        return item;
    }
};
```

### Complexity:
- Time: O(1) push and pop
- Space: O(max_size)

### Explanation:
1. Guard inner std::queue with unique_lock and std::mutex.
2. Use cv_not_full condition variable to block push when at capacity.
3. Use cv_not_empty condition variable to block pop when queue is empty.
4. Notify respective condition variables after state changes.

### Unit Tests:
```cpp
