#include <thread>

void test_blocking_queue() {
    BlockingQueue<int> bq(2);
    std::thread producer([&]() {
        bq.push(100);
        bq.push(200);
    });
    producer.join();
    assert(bq.pop() == 100);
    assert(bq.pop() == 200);
}
```

