class SPSCRingBuffer {
public:
    bool push(const T& item);
    bool pop(T& item);
};

output:
```cpp
#include <atomic>
#include <cstddef>

template<typename T, size_t Capacity>
class SPSCRingBuffer {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of two");
private:
    T buffer_[Capacity];
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
    static constexpr size_t Mask = Capacity - 1;

public:
    SPSCRingBuffer() = default;

    bool push(const T& item) {
        const size_t head = head_.load(std::memory_order_relaxed);
        const size_t tail = tail_.load(std::memory_order_acquire);
        if (head - tail >= Capacity) {
            return false; // Full
        }
        buffer_[head & Mask] = item;
        head_.store(head + 1, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        const size_t tail = tail_.load(std::memory_order_relaxed);
        const size_t head = head_.load(std::memory_order_acquire);
        if (head == tail) {
            return false; // Empty
        }
        item = buffer_[tail & Mask];
        tail_.store(tail + 1, std::memory_order_release);
        return true;
    }
};
```

### Complexity:
- Time: O(1) push and pop
- Space: O(Capacity)

### Explanation:
1. Enforce power-of-two buffer capacity to allow bitwise masking (head & (Capacity - 1)).
2. Use alignas(64) on atomic head and tail to eliminate false sharing between cache lines.
3. Use memory_order_acquire on reading peer's index and memory_order_release on advancing.

### Unit Tests:
```cpp
#include <cassert>

void test_spsc() {
    SPSCRingBuffer<int, 4> rb;
    assert(rb.push(1));
    assert(rb.push(2));
    int val = 0;
    assert(rb.pop(val) && val == 1);
    assert(rb.pop(val) && val == 2);
    assert(!rb.pop(val));
}
```

