class FenwickTree2D {
public:
    FenwickTree2D(int rows, int cols);
    void update(int r, int c, long long val);
    long long query(int r, int c);
    long long query_submatrix(int r1, int c1, int r2, int c2);
};

output:
```cpp
#include <vector>

class FenwickTree2D {
private:
    int rows_, cols_;
    std::vector<std::vector<long long>> tree_;

public:
    FenwickTree2D(int rows, int cols) : rows_(rows), cols_(cols), tree_(rows + 1, std::vector<long long>(cols + 1, 0)) {}

    void update(int r, int c, long long val) {
        for (int i = r; i <= rows_; i += i & -i) {
            for (int j = c; j <= cols_; j += j & -j) {
                tree_[i][j] += val;
            }
        }
    }

    long long query(int r, int c) {
        long long sum = 0;
        for (int i = r; i > 0; i -= i & -i) {
            for (int j = c; j > 0; j -= j & -j) {
                sum += tree_[i][j];
            }
        }
        return sum;
    }

    long long query_submatrix(int r1, int c1, int r2, int c2) {
        return query(r2, c2) - query(r1 - 1, c2) - query(r2, c1 - 1) + query(r1 - 1, c1 - 1);
    }
};
```

### Complexity:
- Time: O(log R * log C) for query and update
- Space: O(R * C)

### Explanation:
1. Use 1-indexed matrix with least significant bit extraction (i & -i).
2. Update propagates value across both dimensions in logarithmic steps.
3. Submatrix queries compute 2D inclusion-exclusion principle sum.

### Unit Tests:
