#include <cassert>

void test_fenwick_2d() {
    FenwickTree2D ft(4, 4);
    ft.update(2, 2, 5);
    ft.update(3, 3, 10);
    assert(ft.query(2, 2) == 5);
    assert(ft.query_submatrix(2, 2, 3, 3) == 15);
    assert(ft.query_submatrix(1, 1, 2, 1) == 0);
}
