import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.function.Supplier;
import java.util.concurrent.atomic.AtomicInteger;

public class ObjectPool<T> {
    private final BlockingQueue<T> pool;
    private final Supplier<T> factory;
    private final int maxSize;
    private final AtomicInteger createdCount = new AtomicInteger(0);

    public ObjectPool(Supplier<T> factory, int maxSize) {
        this.factory = factory;
        this.maxSize = maxSize;
        this.pool = new LinkedBlockingQueue<>(maxSize);
    }

    public T borrowObject() throws InterruptedException {
        T item = pool.poll();
        if (item != null) return item;
        if (createdCount.get() < maxSize && createdCount.incrementAndGet() <= maxSize) {
            return factory.get();
        }
        return pool.take();
    }

    public void returnObject(T obj) {
        if (obj != null) {
            pool.offer(obj);
        }
    }
}
```

### Complexity:
- Time: O(1) amortized borrow and return
- Space: O(maxSize)

### Explanation:
1. Use LinkedBlockingQueue to store ready objects.
2. Lazily create objects up to maxSize using AtomicInteger counter.
3. Block caller on pool.take() when maximum capacity has been leased out.

### Unit Tests:
