public class ObjectPoolTest {
    public static void main(String[] args) throws InterruptedException {
        ObjectPool<StringBuilder> pool = new ObjectPool<>(StringBuilder::new, 2);
        StringBuilder b1 = pool.borrowObject();
        StringBuilder b2 = pool.borrowObject();
        assert b1 != null && b2 != null;
        pool.returnObject(b1);
        StringBuilder b3 = pool.borrowObject();
        assert b3 == b1;
        System.out.println("Object pool tests passed.");
