import java.util.HashMap;
import java.util.Map;

public class CustomReadWriteLock {
    private final Map<Thread, Integer> readingThreads = new HashMap<>();
    private int writeAccesses = 0;
    private int writeRequests = 0;
    private Thread writingThread = null;

    public synchronized void lockRead() throws InterruptedException {
        Thread current = Thread.currentThread();
        while (writingThread != null && writingThread != current || writeRequests > 0 && !readingThreads.containsKey(current)) {
            wait();
        }
        readingThreads.put(current, readingThreads.getOrDefault(current, 0) + 1);
    }

    public synchronized void unlockRead() {
        Thread current = Thread.currentThread();
        int count = readingThreads.getOrDefault(current, 0);
        if (count <= 1) {
            readingThreads.remove(current);
        } else {
            readingThreads.put(current, count - 1);
        }
        notifyAll();
    }

    public synchronized void lockWrite() throws InterruptedException {
        Thread current = Thread.currentThread();
        writeRequests++;
        while ((!readingThreads.isEmpty() && (!readingThreads.containsKey(current) || readingThreads.size() > 1)) || (writingThread != null && writingThread != current)) {
            wait();
        }
        writeRequests--;
        writeAccesses++;
        writingThread = current;
    }

    public synchronized void unlockWrite() {
        if (Thread.currentThread() != writingThread) {
            throw new IllegalMonitorStateException("Current thread does not hold write lock");
        }
        writeAccesses--;
        if (writeAccesses == 0) {
            writingThread = null;
        }
        notifyAll();
    }
}
```

### Complexity:
- Time: O(1) lock and unlock
- Space: O(T) active threads

### Explanation:
1. Track per-thread reentrant read counts via HashMap.
2. Grant write locks only when readingThreads is empty or caller is sole reader.
3. Signal waiting threads via notifyAll() upon releasing locks.

### Unit Tests:
```java
public class CustomReadWriteLockTest {
    public static void main(String[] args) throws Exception {
        CustomReadWriteLock rw = new CustomReadWriteLock();
        rw.lockRead();
        rw.lockRead(); // reentrant
        rw.unlockRead();
        rw.unlockRead();
        rw.lockWrite();
        rw.lockWrite(); // reentrant
        rw.unlockWrite();
        rw.unlockWrite();
