        return sccs;
    }

    private static void dfs(int u, List<List<Integer>> adj, int[] ids, int[] low,
                            boolean[] onStack, Deque<Integer> stack, List<List<Integer>> sccs) {
        ids[u] = low[u] = timer++;
        stack.push(u);
        onStack[u] = true;

        for (int v : adj.get(u)) {
            if (ids[v] == -1) {
                dfs(v, adj, ids, low, onStack, stack, sccs);
                low[u] = Math.min(low[u], low[v]);
            } else if (onStack[v]) {
                low[u] = Math.min(low[u], ids[v]);
            }
        }

        if (low[u] == ids[u]) {
            List<Integer> component = new ArrayList<>();
            while (true) {
                int node = stack.pop();
                onStack[node] = false;
                component.add(node);
                if (node == u) break;
            }
            sccs.add(component);
        }
    }
}
```

### Complexity:
- Time: O(V + E)
- Space: O(V)

### Explanation:
1. Traverse graph via DFS assigning discovery ids and tracking low-link reachability.
2. Maintain execution stack of candidate component vertices.
3. When low[u] == ids[u], pop elements from stack until u to form complete SCC.

