use std::collections::HashMap;

#[derive(Default)]
struct TrieNode {
    children: HashMap<char, TrieNode>,
    frequency: u32,
    is_end: bool,
}

#[derive(Default)]
pub struct Trie {
    root: TrieNode,
}

impl Trie {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn insert(&mut self, word: &str, freq: u32) {
        let mut curr = &mut self.root;
        for c in word.chars() {
            curr = curr.children.entry(c).or_default();
        }
        curr.is_end = true;
        curr.frequency += freq;
    }

    pub fn top_k(&self, prefix: &str, k: usize) -> Vec<(String, u32)> {
        let mut curr = &self.root;
        for c in prefix.chars() {
            if let Some(next) = curr.children.get(&c) {
                curr = next;
            } else {
                return Vec::new();
            }
        }
        let mut matches = Vec::new();
        let mut path = prefix.to_string();
        Self::collect(curr, &mut path, &mut matches);
        matches.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
        matches.truncate(k);
        matches
    }

    fn collect(node: &TrieNode, path: &mut String, results: &mut Vec<(String, u32)>) {
        if node.is_end {
            results.push((path.clone(), node.frequency));
        }
        for (&c, child) in &node.children {
            path.push(c);
            Self::collect(child, path, results);
            path.pop();
        }
    }
}
```

