package main

type DSU struct {
    parent []int
    rank   []int
    Count  int
}

func NewDSU(n int) *DSU {
    parent := make([]int, n)
    rank := make([]int, n)
    for i := range parent {
        parent[i] = i
        rank[i] = 0
    }
    return &DSU{parent: parent, rank: rank, Count: n}
}

func (d *DSU) Find(x int) int {
    if d.parent[x] != x {
        d.parent[x] = d.Find(d.parent[x]) // path compression
    }
    return d.parent[x]
}

func (d *DSU) Union(x, y int) bool {
    rootX := d.Find(x)
    rootY := d.Find(y)
    if rootX == rootY {
        return false // already connected
    }
    if d.rank[rootX] < d.rank[rootY] {
        d.parent[rootX] = rootY
    } else if d.rank[rootX] > d.rank[rootY] {
        d.parent[rootY] = rootX
    } else {
        d.parent[rootY] = rootX
        d.rank[rootX]++
    }
    d.Count--
    return true
}
```

### Complexity:
- Time: O(α(N)) nearly constant per operation
- Space: O(N)

### Explanation:
1. Initialize parent pointers pointing to self and zero ranks.
2. Apply path compression during Find() flattening tree depth.
3. Attach shorter tree under taller tree during Union() to maintain logarithmic height.

