function isPalindrome(string $text): bool {
    $clean = mb_strtolower((string) preg_replace('/[^\p{L}\p{N}]/u', '', $text), 'UTF-8');
    $len = mb_strlen($clean, 'UTF-8');
    for ($i = 0; $i < intdiv($len, 2); $i++) {
