    $cleanB = mb_strtolower((string) preg_replace('/[^\p{L}\p{N}]/u', '', $b), 'UTF-8');
    if (mb_strlen($cleanA, 'UTF-8') !== mb_strlen($cleanB, 'UTF-8')) return false;
    $charsA = preg_split('//u', $cleanA, -1, PREG_SPLIT_NO_EMPTY);
    $charsB = preg_split('//u', $cleanB, -1, PREG_SPLIT_NO_EMPTY);
    sort($charsA);
    sort($charsB);
    return $charsA === $charsB;
}
