declare(strict_types=1);

class LruNode {
    public function __construct(
        public int|string $key,
        public mixed $val,
        public ?LruNode $prev = null,
        public ?LruNode $next = null,
    ) {}
}

class LruCachePhp {
    private array $map = [];
    private LruNode $head;
    private LruNode $tail;

    public function __construct(private int $capacity) {
        $this->head = new LruNode(0, null);
        $this->tail = new LruNode(0, null);
        $this->head->next = $this->tail;
        $this->tail->prev = $this->head;
    }

    public function get(int|string $key): mixed {
        if (!isset($this->map[$key])) return null;
        $node = $this->map[$key];
        $this->moveToHead($node);
        return $node->val;
    }

    public function put(int|string $key, mixed $value): void {
        if (isset($this->map[$key])) {
            $node = $this->map[$key];
            $node->val = $value;
            $this->moveToHead($node);
            return;
        }
        if (count($this->map) >= $this->capacity) {
            $lru = $this->tail->prev;
            $this->removeNode($lru);
            unset($this->map[$lru->key]);
        }
        $newNode = new LruNode($key, $value);
        $this->addNode($newNode);
        $this->map[$key] = $newNode;
    }

    private function addNode(LruNode $node): void {
        $node->prev = $this->head;
        $node->next = $this->head->next;
        $this->head->next->prev = $node;
        $this->head->next = $node;
    }

    private function removeNode(LruNode $node): void {
        $node->prev->next = $node->next;
        $node->next->prev = $node->prev;
    }

    private function moveToHead(LruNode $node): void {
        $this->removeNode($node);
        $this->addNode($node);
    }
}
```

